  const rows = await Promise.all(
    voyageIds.map((voyageId) =>
      db
        .select()
        .from(maritimeDocumentExtractions)
        .where(and(eq(maritimeDocumentExtractions.workspaceId, workspaceId), eq(maritimeDocumentExtractions.voyageId, voyageId))),
